<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'; import type { Account, AccountPlatform, AccountType, AdminGroup, CreateAccountRequest, Proxy, UpdateAccountRequest } from '@/types'; import SurfaceDialog from '@/components/base/SurfaceDialog.vue'; import { DialogWidth } from '@/components/base/dialog'; import AccountCredentialWizard from './AccountCredentialWizard.vue'; import AccountPlatformConfigEditor from './AccountPlatformConfigEditor.vue'; import { AccountEditorTab, accountDraftToRequest, accountToDraft, emptyAccountDraft, type AccountDraft } from '@/features/admin/resources/account'; import { useAppStore } from '@/stores/app'
enum AccountPlatformOption { OPENAI = 'openai', ANTHROPIC = 'anthropic', GEMINI = 'gemini', ANTIGRAVITY = 'antigravity', GROK = 'grok', KIMI = 'kimi', ZHIPU = 'zhipu', DEEPSEEK = 'deepseek' }
enum AccountTypeOption { OAUTH = 'oauth', SETUP_TOKEN = 'setup-token', API_KEY = 'apikey', UPSTREAM = 'upstream', BEDROCK = 'bedrock', SERVICE_ACCOUNT = 'service_account' }
const props = defineProps<{ show: boolean; account: Account | null; groups: AdminGroup[]; proxies: Proxy[]; submitting?: boolean }>(); const emit = defineEmits<{ close: []; submit: [payload: CreateAccountRequest | UpdateAccountRequest] }>(); const app = useAppStore(); const tab = ref(AccountEditorTab.BASIC); const form = reactive<AccountDraft>(emptyAccountDraft())
const platforms: Array<{ value: AccountPlatform; label: string }> = [{ value: AccountPlatformOption.OPENAI, label: 'OpenAI / Codex' }, { value: AccountPlatformOption.ANTHROPIC, label: 'Anthropic / Claude' }, { value: AccountPlatformOption.GEMINI, label: 'Google Gemini' }, { value: AccountPlatformOption.ANTIGRAVITY, label: 'Antigravity' }, { value: AccountPlatformOption.GROK, label: 'Grok' }, { value: AccountPlatformOption.KIMI, label: 'Kimi' }, { value: AccountPlatformOption.ZHIPU, label: '智谱' }, { value: AccountPlatformOption.DEEPSEEK, label: 'DeepSeek' }]
const typeLabels: Record<AccountType, string> = { [AccountTypeOption.OAUTH]: 'OAuth', [AccountTypeOption.SETUP_TOKEN]: 'Setup Token', [AccountTypeOption.API_KEY]: 'API Key', [AccountTypeOption.UPSTREAM]: '上游账号', [AccountTypeOption.BEDROCK]: 'Amazon Bedrock', [AccountTypeOption.SERVICE_ACCOUNT]: 'Service Account' }
const platformTypes: Record<AccountPlatform, AccountType[]> = {
  [AccountPlatformOption.OPENAI]: [AccountTypeOption.OAUTH, AccountTypeOption.SETUP_TOKEN, AccountTypeOption.API_KEY],
  [AccountPlatformOption.ANTHROPIC]: [AccountTypeOption.OAUTH, AccountTypeOption.SETUP_TOKEN, AccountTypeOption.API_KEY, AccountTypeOption.BEDROCK, AccountTypeOption.SERVICE_ACCOUNT],
  [AccountPlatformOption.GEMINI]: [AccountTypeOption.OAUTH, AccountTypeOption.API_KEY, AccountTypeOption.SERVICE_ACCOUNT],
  [AccountPlatformOption.ANTIGRAVITY]: [AccountTypeOption.OAUTH, AccountTypeOption.UPSTREAM],
  [AccountPlatformOption.GROK]: [AccountTypeOption.OAUTH, AccountTypeOption.API_KEY],
  [AccountPlatformOption.KIMI]: [AccountTypeOption.API_KEY],
  [AccountPlatformOption.ZHIPU]: [AccountTypeOption.API_KEY],
  [AccountPlatformOption.DEEPSEEK]: [AccountTypeOption.API_KEY],
  minimax: [AccountTypeOption.API_KEY]
}
const typeOptions = computed(() => platformTypes[form.platform].map(value => ({ value, label: typeLabels[value] })))
function toggleGroup(id: number): void { form.group_ids = form.group_ids.includes(id) ? form.group_ids.filter(item => item !== id) : [...form.group_ids, id] }
function submit(): void { try { emit('submit', accountDraftToRequest(form, Boolean(props.account))) } catch (caught) { app.showError((caught as Error).message) } }
watch(() => props.show, (show) => { if (show) { Object.assign(form, props.account ? accountToDraft(props.account) : emptyAccountDraft()); tab.value = AccountEditorTab.BASIC } })
watch(() => form.platform, () => { if (!platformTypes[form.platform].includes(form.type)) form.type = platformTypes[form.platform][0] })
</script>
<template><SurfaceDialog :show="show" :title="account ? '编辑上游账号' : '创建上游账号'" description="平台凭据、模型映射、故障恢复和调度策略均提供显式控件；未知扩展字段仍可通过原始 JSON 访问。" :width="DialogWidth.WIDE" @close="emit('close')"><form id="account-editor-form" class="resource-form-stack" @submit.prevent="submit"><div class="resource-tabs"><button type="button" :aria-selected="tab === AccountEditorTab.BASIC" @click="tab = AccountEditorTab.BASIC">身份与绑定</button><button type="button" :aria-selected="tab === AccountEditorTab.CREDENTIALS" @click="tab = AccountEditorTab.CREDENTIALS">凭据与高级</button><button type="button" :aria-selected="tab === AccountEditorTab.SCHEDULING" @click="tab = AccountEditorTab.SCHEDULING">调度与配额</button></div>
  <div v-if="tab === AccountEditorTab.BASIC" class="resource-form-stack"><div class="resource-form-grid resource-form-grid--3"><label class="resource-field--wide">账号名称 *<input v-model="form.name" /></label><label class="resource-field--wide">备注<textarea v-model="form.notes" rows="3" /></label><label>平台<select v-model="form.platform" :disabled="Boolean(account)"><option v-for="item in platforms" :key="item.value" :value="item.value">{{ item.label }}</option></select></label><label>账号类型<select v-model="form.type"><option v-for="item in typeOptions" :key="item.value" :value="item.value">{{ item.label }}</option></select></label><label v-if="account">状态<select v-model="form.status"><option value="active">启用</option><option value="inactive">停用</option><option value="error">异常</option></select></label><label>代理<select v-model="form.proxy_id"><option value="">直连</option><option v-for="proxy in proxies" :key="proxy.id" :value="proxy.id">{{ proxy.name }} · {{ proxy.host }}</option></select></label><label>到期时间<input v-model="form.expires_at" type="datetime-local" /></label><label class="resource-check"><input v-model="form.auto_pause_on_expired" type="checkbox" /><span>到期自动暂停</span></label></div><fieldset class="resource-form-section"><legend>绑定分组</legend><div class="account-group-grid"><label v-for="group in groups.filter(item => item.platform === form.platform || item.platform === 'composite')" :key="group.id" class="resource-check"><input type="checkbox" :checked="form.group_ids.includes(group.id)" @change="toggleGroup(group.id)" /><span>{{ group.name }} · {{ group.rate_multiplier }}×</span></label></div></fieldset></div>
  <div v-else-if="tab === AccountEditorTab.CREDENTIALS" class="resource-form-stack"><AccountCredentialWizard v-if="!account && (form.type === AccountTypeOption.OAUTH || form.type === AccountTypeOption.SETUP_TOKEN)" :platform="form.platform" :type="form.type" :proxy-id="form.proxy_id" :credentials-json="form.credentials_json" :extra-json="form.extra_json" @update:credentials-json="form.credentials_json = $event" @update:extra-json="form.extra_json = $event" /><AccountPlatformConfigEditor :account="account" :platform="form.platform" :type="form.type" :credentials-json="form.credentials_json" :extra-json="form.extra_json" @update:credentials-json="form.credentials_json = $event" @update:extra-json="form.extra_json = $event" /><details class="raw-config"><summary>高级兼容：编辑原始 JSON</summary><div class="resource-form-stack"><label>凭据 JSON<textarea v-model="form.credentials_json" rows="10" class="resource-code" spellcheck="false" /></label><label>Extra / 平台高级配置 JSON<textarea v-model="form.extra_json" rows="14" class="resource-code" spellcheck="false" /></label><p class="muted">用于访问尚未图形化的兼容字段。敏感凭据不会从后端回显，留空即保留原值。</p></div></details></div>
  <div v-else class="resource-form-stack"><fieldset class="resource-form-section"><legend>调度</legend><div class="resource-form-grid resource-form-grid--4"><label>并发<input v-model.number="form.concurrency" type="number" min="1" step="1" /></label><label>负载系数<input v-model="form.load_factor" type="number" min="0" step="any" /></label><label>优先级<input v-model.number="form.priority" type="number" step="1" /></label><label>计费倍率<input v-model="form.rate_multiplier" type="number" min="0" step="any" /></label><label v-if="account" class="resource-check"><input v-model="form.schedulable" type="checkbox" /><span>参与调度</span></label><label class="resource-check"><input v-model="form.upstream_billing_probe_enabled" type="checkbox" /><span>上游计费探测</span></label><label class="resource-check"><input v-model="form.upstream_billing_rate_sync_enabled" type="checkbox" /><span>同步上游倍率</span></label></div></fieldset><fieldset class="resource-form-section"><legend>窗口、会话与 RPM</legend><div class="resource-form-grid resource-form-grid--4"><label>窗口费用上限<input v-model="form.window_cost_limit" type="number" min="0" step="any" /></label><label>粘性预留<input v-model="form.window_cost_sticky_reserve" type="number" min="0" step="any" /></label><label>最大会话数<input v-model="form.max_sessions" type="number" min="0" step="1" /></label><label>会话空闲分钟<input v-model="form.session_idle_timeout_minutes" type="number" min="0" step="1" /></label><label>基础 RPM<input v-model="form.base_rpm" type="number" min="0" step="1" /></label><label>RPM 策略<select v-model="form.rpm_strategy"><option value="">默认</option><option value="tiered">tiered</option><option value="sticky_exempt">sticky_exempt</option></select></label><label>RPM 粘性缓冲<input v-model="form.rpm_sticky_buffer" type="number" min="0" step="any" /></label><label>用户消息队列<select v-model="form.user_msg_queue_mode"><option value="">关闭</option><option value="serialize">serialize</option><option value="throttle">throttle</option></select></label></div></fieldset><fieldset class="resource-form-section"><legend>指纹与请求覆盖</legend><div class="resource-form-grid resource-form-grid--3"><label class="resource-check"><input v-model="form.enable_tls_fingerprint" type="checkbox" /><span>TLS 指纹模拟</span></label><label v-if="form.enable_tls_fingerprint">指纹档案 ID<input v-model="form.tls_fingerprint_profile_id" type="number" min="1" /></label><label class="resource-check"><input v-model="form.session_id_masking_enabled" type="checkbox" /><span>会话 ID 模拟</span></label><label class="resource-check"><input v-model="form.cache_ttl_override_enabled" type="checkbox" /><span>覆盖缓存 TTL</span></label><label v-if="form.cache_ttl_override_enabled">TTL 目标<input v-model="form.cache_ttl_override_target" /></label><label class="resource-check"><input v-model="form.custom_base_url_enabled" type="checkbox" /><span>自定义 Base URL</span></label><label v-if="form.custom_base_url_enabled" class="resource-field--wide">Base URL<input v-model="form.custom_base_url" type="url" /></label></div></fieldset><fieldset class="resource-form-section"><legend>API Key 配额与固定重置</legend><div class="resource-form-grid resource-form-grid--4"><label>总配额<input v-model="form.quota_limit" type="number" min="0" step="any" /></label><label>每日配额<input v-model="form.quota_daily_limit" type="number" min="0" step="any" /></label><label>每周配额<input v-model="form.quota_weekly_limit" type="number" min="0" step="any" /></label><label>时区<input v-model="form.quota_reset_timezone" /></label><label>每日模式<select v-model="form.quota_daily_reset_mode"><option value="">默认</option><option value="rolling">rolling</option><option value="fixed">fixed</option></select></label><label>每日小时<input v-model="form.quota_daily_reset_hour" type="number" min="0" max="23" /></label><label>每周模式<select v-model="form.quota_weekly_reset_mode"><option value="">默认</option><option value="rolling">rolling</option><option value="fixed">fixed</option></select></label><label>每周星期<input v-model="form.quota_weekly_reset_day" type="number" min="0" max="6" /></label><label>每周小时<input v-model="form.quota_weekly_reset_hour" type="number" min="0" max="23" /></label></div></fieldset></div>
  </form><template #footer><button class="button button--secondary" @click="emit('close')">取消</button><button type="submit" form="account-editor-form" class="button button--primary" :disabled="submitting">{{ submitting ? '保存中…' : '保存账号' }}</button></template></SurfaceDialog></template>
<style scoped>.account-group-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }.raw-config { padding: 12px 14px; border: 1px dashed var(--border-subtle); border-radius: 10px; }.raw-config summary { color: var(--text-secondary); font-size: var(--font-body-sm); font-weight: 700; cursor: pointer; }.raw-config[open] summary { margin-bottom: 12px; } @media(max-width:650px){.account-group-grid{grid-template-columns:1fr}}</style>
